// Generated by build-site.mjs. Atomic, revisioned local game shell; no save data.
const PREFIX=`lions-gate-shell-${new URL(self.registration.scope).pathname}-`;
const CACHE=PREFIX+'__REVISION__';
const FILES=__FILES__;
const urls=FILES.map(file=>new URL(file,self.registration.scope).href);
self.addEventListener('install',event=>{
 event.waitUntil((async()=>{
  const cache=await caches.open(CACHE);
  try{await cache.addAll(urls.map(url=>new Request(url,{cache:'reload'})))}
  catch(error){await caches.delete(CACHE);throw error}
 })());
 // Deliberately no skipWaiting: do not replace code under an active game.
});
self.addEventListener('activate',event=>{
 event.waitUntil((async()=>{
  for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);
 })());
});
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url),base=new URL(self.registration.scope);
 if(event.request.method!=='GET'||url.origin!==base.origin)return;
 const home=event.request.mode==='navigate'&&(url.pathname===base.pathname||url.pathname===base.pathname+'index.html');
 const key=home?new URL('index.html',base).href:url.href;
 if(!home&&!urls.includes(key))return;
 event.respondWith((async()=>{
  const cached=await (await caches.open(CACHE)).match(key);
  return cached||fetch(event.request);
 })());
});
